INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(4601, 'Deuteronomy 4:20', 'Deuteronomy', 4, 20, '&nbsp;خو تاسو هغه خلق يئ چې مالِک خُدائ د مِصر نه راوويستلئ چرته چې تاسو د اور په تنور کښې وئ. هغۀ تاسو ځکه راوويستلئ چې هغه تاسو خپل خلق جوړ کړى لکه چې نن تاسو يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4602, 'Deuteronomy 4:21', 'Deuteronomy', 4, 21, '&nbsp;خو ستاسو په وجه مالِک خُدائ ستاسو خُدائ پاک ما ته غصه وو او دا قسم يې وخوړو چې تۀ به د اُردن سيند نه پورې نۀ وځې چې هغه آباد مُلک ته لاړ شى کوم چې هغه تاسو له درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4603, 'Deuteronomy 4:22', 'Deuteronomy', 4, 22, '&nbsp;زۀ به په دې مُلک کښې مړ شم او هيڅکله به د سيند نه پورې نۀ وځم، خو هغه وخت نزدې دے چې تاسو به واوړئ او هغه آباده زمکه به قبضه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4604, 'Deuteronomy 4:23', 'Deuteronomy', 4, 23, '&nbsp;پام کوئ. مالِک خُدائ ستاسو خُدائ پاک چې تاسو سره کوم لوظ کړے دے هغه مۀ هېروئ. د هغۀ حُکم منئ چې يو قِسم بُت هم مۀ جوړَوئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4605, 'Deuteronomy 4:24', 'Deuteronomy', 4, 24, '&nbsp;ځکه چې مالِک خُدائ ستاسو خُدائ پاک د يو بل شوى اور په شان دے، او غېرتى خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4606, 'Deuteronomy 4:25', 'Deuteronomy', 4, 25, '&nbsp;تر دې پورې چې تاسو به په هغه مُلک کښې تر ډېره وخته پورې يئ او بچى او نمسى به مو پېدا شى، د يو څيز په شکل هم بُت جوړولو په وجه خپل ځانونه مۀ ګناهګاروئ. د مالِک خُدائ په نظر کښې دا يو بد عمل دے او د دې په وجه به هغه غصه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4607, 'Deuteronomy 4:26', 'Deuteronomy', 4, 26, '&nbsp;نن زۀ آسمان او زمکه ستاسو خِلاف ګواهان جوړوم، کۀ تاسو زما نافرمانى وکړئ، نو تاسو به زر د زمکې نه ورک شئ. تاسو به په هغه مُلک کښې ډېره موده ژوند ونۀ کړئ کوم چې د اُردن نه پورې دے او تاسو يې قبضه کوئ. تاسو به تباه شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4608, 'Deuteronomy 4:27', 'Deuteronomy', 4, 27, '&nbsp;مالِک خُدائ به تاسو په نورو قومونو کښې خوارۀ وارۀ کړى، هلته به صِرف يو څو کسان ستاسو نه ژوندى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4609, 'Deuteronomy 4:28', 'Deuteronomy', 4, 28, '&nbsp;هلته به تاسو د داسې معبودانو خِدمت کوئ چې انسان جوړ کړى وى، د لرګو او د کاڼو معبودان، هغه معبودان چې نۀ ليدل او نۀ اورېدل کولے شى، نۀ خوراک او نۀ بويول کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4610, 'Deuteronomy 4:29', 'Deuteronomy', 4, 29, '&nbsp;خو کۀ هلته تاسو مالِک خُدائ خپل خُدائ پاک ولټوئ او د زړۀ د اخلاصه او د خپل ټول روح سره د هغۀ لټون وکړئ نو تاسو به هغه ومومئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4611, 'Deuteronomy 4:30', 'Deuteronomy', 4, 30, '&nbsp;کله چې تاسو په تکليف کښې يئ او په تاسو باندې دا هر څۀ تېر شوى وى، نو آخر به مالِک خُدائ ته راواپس شئ او د هغۀ تابعدارى به وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4612, 'Deuteronomy 4:31', 'Deuteronomy', 4, 31, '&nbsp;هغه رحم کوونکے خُدائ پاک دے. هغه به تاسو نۀ پرېږدى او نۀ به مو تباه کوى او هغه به هغه لوظ نۀ هېروى چې کوم هغۀ په خپله ستاسو پلار نيکۀ سره کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4613, 'Deuteronomy 4:32', 'Deuteronomy', 4, 32, '&nbsp;تاريخ ته وګورئ. ستاسو د پېدايښت نه مخکښې وخت، او وروستو وخت او زمانې ته وګورئ کله چې مالِک خُدائ بنى آدم په زمکه پېدا کړو. ټوله دُنيا ولټوئ. د دې په شان لوئ کار مخکښې کله هم شوے دے څۀ؟ ولې مخکښې چا د دې په شان څۀ اورېدلى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4614, 'Deuteronomy 4:33', 'Deuteronomy', 4, 33, '&nbsp;داسې څۀ خلق شته چې هغوئ د اور نه د يو خُدائ خبرې اورېدلې وى او ژوندى پاتې وى لکه ستاسو په شان؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4615, 'Deuteronomy 4:34', 'Deuteronomy', 4, 34, '&nbsp;بل خُدائ کله هم دا جرأت کړے دے چې د بل قوم نه خلق روان کړى او بو يې ځى او هغوئ خپل خلق جوړ کړى، لکه څنګه چې مالِک خُدائ ستاسو خُدائ پاک ستاسو دپاره په مِصر کښې وکړل؟ ستاسو د سترګو په وړاندې هغۀ د خپل لوئ طاقت او قوت نه کار واخستلو، هغۀ وباګانې او جنګ راوستلو، معجزې او نښې يې وښودلې او يروونکى کارونه يې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4616, 'Deuteronomy 4:35', 'Deuteronomy', 4, 35, '&nbsp;مالِک خُدائ تاسو ته دا وښودل چې دا ثابِته شى چې يواځې هغه خُدائ پاک دے او بې له هغۀ نه بل نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4617, 'Deuteronomy 4:36', 'Deuteronomy', 4, 36, '&nbsp;هغۀ په تاسو باندې د آسمان نه خپل آواز واورېدو چې هغه ستاسو تربيت وکړى، او هغۀ دلته په زمکه باندې په تاسو خپل مقدس اور وليدلو او د دې نه يې تاسو سره خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4618, 'Deuteronomy 4:37', 'Deuteronomy', 4, 37, '&nbsp;ځکه چې هغۀ ستاسو پلار نيکۀ سره مينه کوله، هغۀ تاسو غوره کړئ او د خپل لوئ طاقت سره هغۀ په خپله تاسو د مِصر نه راوويستلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4619, 'Deuteronomy 4:38', 'Deuteronomy', 4, 38, '&nbsp;کله چې تاسو مخ په وړاندې روان وئ، نو هغۀ هغه قومونه وشړل چې ستاسو نه لوئ او طاقتور وُو، چې هغه تاسو د هغوئ مُلک ته راولى او در يې کړى، کوم مُلک چې نن هم ستاسو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4620, 'Deuteronomy 4:39', 'Deuteronomy', 4, 39, '&nbsp;نو نن دا خبره ياده ساتئ او هيڅکله يې مۀ هېروئ. مالِک خُدائ هغه خُدائ پاک دے چې په آسمان کښې او لاندې په زمکه کښې موجود دے. بل يو خُدائ هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4621, 'Deuteronomy 4:40', 'Deuteronomy', 4, 40, '&nbsp;د هغۀ ټول قانون ومنئ کوم چې نن ما تاسو له درکړے دے، نو ستاسو او ستاسو د اولاد به هر کار سم وى. په هغه مُلک کښې به اوسېږئ کوم چې مالِک خُدائ ستاسو خُدائ پاک همېشه دپاره تاسو له درکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4622, 'Deuteronomy 4:41', 'Deuteronomy', 4, 41, '&nbsp;بيا موسىٰ د اُردن سيند نمرخاتۀ طرف ته درې ښارونه بېل کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4623, 'Deuteronomy 4:42', 'Deuteronomy', 4, 42, '&nbsp;کله چې څوک په غلطۍ سره داسې څوک ووژنى چې دشمنى يې ورسره نۀ وى نو قاتِل به د دې ښارونو نه يو ښار ته د پناه دپاره وتښتى او خپل ژوند به بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4624, 'Deuteronomy 4:43', 'Deuteronomy', 4, 43, '&nbsp;د لوړې علاقې په بيابان کښې د بصر ښار، د روبين قبيلې دپاره وو، د جِلعاد په علاقې کښې، د رامات ښار د جاد قبيلې دپاره وو، د بسن په علاقه کښې، جولان د منسى قبيلې دپاره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4625, 'Deuteronomy 4:44', 'Deuteronomy', 4, 44, '&nbsp;موسىٰ بنى اِسرائيلو ته د خُدائ پاک قانون او اصُول وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4626, 'Deuteronomy 4:47', 'Deuteronomy', 4, 47, '&nbsp;هغوئ د هغۀ او د بسن بادشاه عوج په مُلک قبضه وکړه، دا د اموريانو بل بادشاه وو چې د اُردن نمرخاتۀ طرف ته اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4627, 'Deuteronomy 4:48', 'Deuteronomy', 4, 48, '&nbsp;دا مُلک د ارنون سيند په غاړه، د عروعير ښار نه واخله، د سِريون غرۀ پورې خور وو، کوم چې حرمون دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4628, 'Deuteronomy 4:49', 'Deuteronomy', 4, 49, '&nbsp;په دې کښې هغه ټوله علاقه هم شامله وه چې د اُردن سيند نمرخاتۀ طرف ته د مالګې درياب پورې وه او د پِسګه د غرۀ تر لمنې پورې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4629, 'Deuteronomy 5:1', 'Deuteronomy', 5, 1, '&nbsp;موسىٰ ټول اِسرائيليان راغونډ کړل او هغوئ ته يې وفرمائيل، ”اے بنى اِسرائيلو. دې قانون ته غوږ ونيسئ کوم چې نن زۀ تاسو له درکوم. دا زده کړئ او وګورئ چې خامخا به ورباندې عمل وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4630, 'Deuteronomy 5:2', 'Deuteronomy', 5, 2, '&nbsp;د سينا په غرۀ باندې مالِک خُدائ زمونږ خُدائ پاک يو لوظ وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4631, 'Deuteronomy 5:3', 'Deuteronomy', 5, 3, '&nbsp;هغه لوظ نۀ صِرف زمونږ د پلار نيکۀ سره وو، بلکې زمونږ ټولو سره وو کوم چې نن ژوندى يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4632, 'Deuteronomy 5:4', 'Deuteronomy', 5, 4, '&nbsp;مالِک خُدائ هلته په غرۀ باندې د اور نه تاسو سره مخامخ خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4633, 'Deuteronomy 5:5', 'Deuteronomy', 5, 5, '&nbsp;په هغه وخت کښې زۀ ستاسو او مالِک خُدائ په مينځ کښې د مينځګړى په شان د دې دپاره ولاړ وم چې هغه څۀ ووائى نو زۀ به يې تاسو ته ووايم، ځکه چې تاسو د اور نه يرېدئ او غرۀ ته ونۀ ختلئ. مالِک خُدائ وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4634, 'Deuteronomy 5:6', 'Deuteronomy', 5, 6, '&nbsp;زۀ مالِک خُدائ ستاسو خُدائ پاک يم، چا چې د مِصر نه راوويستلئ، چرته چې تاسو غلامان وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4635, 'Deuteronomy 5:7', 'Deuteronomy', 5, 7, '&nbsp;زما نه غېر د نورو معبودانو عبادت مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4636, 'Deuteronomy 5:8', 'Deuteronomy', 5, 8, '&nbsp;د ځان دپاره د داسې يو څيز په شکل هم بُتان مۀ جوړَوئ چې هغه پاس په آسمان کښې وى يا لاندې په زمکه باندې وى او يا د زمکې د لاندې په اوبو کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4637, 'Deuteronomy 5:9', 'Deuteronomy', 5, 9, '&nbsp;يو بُت ته هم چې سجده ونۀ لګوئ او نۀ يې عبادت وکړئ، ځکه چې زۀ مالِک خُدائ ستاسو غېرتى خُدائ پاک يم. زۀ د پلار نيکۀ د ګناه سزا د هغوئ اولاد له تر درېم او څلورم نسله پورې ورکوم څوک چې زما نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4638, 'Deuteronomy 5:10', 'Deuteronomy', 5, 10, '&nbsp;خو زۀ د هغه خلقو زرګونو نسلونو ته خپله مينه ښايم څوک چې زما سره مينه لرى او زما حُکمونه منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4639, 'Deuteronomy 5:11', 'Deuteronomy', 5, 11, '&nbsp;زما نوم د غلطو مقصدونو دپاره مۀ استعمالوئ، ځکه چې زۀ، مالِک خُدائ ستاسو خُدائ پاک به هغه چا له سزا ورکوم څوک چې زما نوم بې‌ځايه اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4640, 'Deuteronomy 5:12', 'Deuteronomy', 5, 12, '&nbsp;د سبت ورځ ياده لرئ او دا مقدسه وګڼئ، هم هغه شان لکه څنګه چې ما، مالِک خُدائ ستاسو خُدائ پاک حُکم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4641, 'Deuteronomy 5:13', 'Deuteronomy', 5, 13, '&nbsp;په شپږو ورځو کښې تاسو خپل کار روزګار کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4642, 'Deuteronomy 5:14', 'Deuteronomy', 5, 14, '&nbsp;خو اوومه ورځ د آرام ورځ ده چې ما ته وقف ده. په هغه ورځ به هيڅ څوک کار نۀ کوى، نۀ تاسو، نۀ ستاسو بچى، نۀ ستاسو غلامان، نۀ ستاسو ځناور او نۀ هغه مسافر چې ستاسو په مُلک کښې اوسيږى. ستاسو غلامان به هم هغه شان آرام کوى لکه څنګه چې تاسو کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4643, 'Deuteronomy 5:15', 'Deuteronomy', 5, 15, '&nbsp;هغه راپه ياد کړئ چې تاسو په مِصر کښې غلامان وئ او ما، مالِک خُدائ، ستاسو خُدائ پاک د خپل لوئ طاقت او قوت سره آزاد کړئ. نو ځکه زۀ تاسو له حُکم درکوم چې د سبت ورځ ياده لرئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4644, 'Deuteronomy 5:16', 'Deuteronomy', 5, 16, '&nbsp;د خپل مور او پلار عزت کوئ، لکه چې زۀ، مالِک خُدائ، ستاسو خُدائ پاک تاسو له حُکم درکوم، نو ستاسو هر څۀ به سم وى او تاسو به په هغه مُلک کښې يو اوږد عمر تېر کړئ کوم چې درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4645, 'Deuteronomy 5:17', 'Deuteronomy', 5, 17, '&nbsp;قتل مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4646, 'Deuteronomy 5:18', 'Deuteronomy', 5, 18, '&nbsp;زنا مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4647, 'Deuteronomy 5:19', 'Deuteronomy', 5, 19, '&nbsp;غلا مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4648, 'Deuteronomy 5:20', 'Deuteronomy', 5, 20, '&nbsp;د چا خِلاف د دروغو ګواهى مۀ ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4649, 'Deuteronomy 5:21', 'Deuteronomy', 5, 21, '&nbsp;د بل سړى د ښځې خواهش مۀ کوئ، د هغۀ د کور، د هغۀ د زمکې، د هغۀ د نوکرانو، د هغۀ د څاروو، د هغۀ د خرونو، يا د بل داسې يو شى لالچ هم مۀ کوئ کوم چې د هغۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4650, 'Deuteronomy 5:22', 'Deuteronomy', 5, 22, '&nbsp;کله چې تاسو د غرۀ سره راغونډ وئ نو دا حُکمونه مالِک خُدائ تاسو ټولو له درکړل. کله چې هغۀ د اور نه او د تکې تورې وريځې نه په يو دروند آواز سره خبرې وکړې نو هم دغه حُکمونه يې درکړل. بيا هغۀ دا د کاڼو په دوه تختو وليکل او ما له يې راکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4651, 'Deuteronomy 5:23', 'Deuteronomy', 5, 23, '&nbsp;کله چې ټول غر اور اخستے وو او تاسو د تيارې نه آواز واورېدو، نو ستاسو د قبيلو مشران ما له راغلل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4652, 'Deuteronomy 5:24', 'Deuteronomy', 5, 24, '&nbsp;او هغوئ ووئيل چې مالِک خُدائ زمونږ خُدائ پاک مونږ ته خپله لوئى او جلال په هغه وخت وښودلو چې د اور نه مو د هغۀ خبرې اورېدلې. مونږ ته نن دا پته ولګېده چې کۀ خُدائ پاک د يو انسان سره خبرې وکړى نو هغه انسان بيا هم ژوندے پاتې کېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4653, 'Deuteronomy 5:25', 'Deuteronomy', 5, 25, '&nbsp;خو مونږ ولې خپل ځانونه د مرګ په خطره کښې واچوو؟ هغه لوئ اور به مونږ تباه کړى. زمونږ دا يقين دے کۀ چرې بيا مونږ د مالِک خُدائ زمونږ د خُدائ پاک خبرې واورېدلې نو مړۀ به شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4654, 'Deuteronomy 5:26', 'Deuteronomy', 5, 26, '&nbsp;داسې يو انسان شته څۀ چې هغۀ د اور نه د ژوندى خُدائ پاک خبرې اورېدلې وى او بيا هم ژوندے پاتې وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4655, 'Deuteronomy 5:27', 'Deuteronomy', 5, 27, '&nbsp;موسىٰ، واپس لاړ شه او هغه هر څۀ په غور سره واوره څۀ چې مالِک خُدائ زمونږ خُدائ پاک فرمائى. بيا واپس راشه او چې هغۀ درته څۀ وئيلى وى نو هغه مونږ ته ووايه. مونږ به هغې ته غوږ ونيسو او عمل به پرې وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4656, 'Deuteronomy 5:28', 'Deuteronomy', 5, 28, '&nbsp;کله چې مالِک خُدائ دا واورېدل، نو هغۀ ما ته وفرمائيل، ما د دې خلقو خبرې اورېدلې دى او هغوئ بلکل ټيک وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4657, 'Deuteronomy 5:29', 'Deuteronomy', 5, 29, '&nbsp;کاش چې هغوئ همېشه صِرف هم دغه شان احساس لرلے. کاش چې هغوئ همېشه زما درناوے کولے او زما ټول حُکمونه يې منلے، نو چې د هغوئ او د هغوئ د اولاد به همېشه دپاره هر څۀ سم وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4658, 'Deuteronomy 5:30', 'Deuteronomy', 5, 30, '&nbsp;لاړ شه او هغوئ ته ووايه چې واپس خپلو خېمو ته لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4659, 'Deuteronomy 5:31', 'Deuteronomy', 5, 31, '&nbsp;خو موسىٰ، تۀ، زما سره ايسار شه او زۀ به تا له زما ټول حُکمونه درکړم. هغه بيا خلقو ته وښايه، چې هغوئ په دې باندې په هغه مُلک کښې عمل کوى کوم چې هغوئ له ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4660, 'Deuteronomy 5:32', 'Deuteronomy', 5, 32, '&nbsp;بنى اِسرائيلو، ګورئ چې تاسو هغه هر څۀ وکړئ د کوم چې مالِک خُدائ ستاسو خُدائ پاک تاسو له حُکم درکړے دے. او د دې قانون نه اخوا دېخوا مۀ اوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4661, 'Deuteronomy 5:33', 'Deuteronomy', 5, 33, '&nbsp;په هغه ټولو حُکمونو عمل کوئ، نو ستاسو هر څۀ به سم وى او په هغه مُلک کښې به تاسو ژوند تېروئ د کوم قبضه کولو له چې تاسو روان يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4662, 'Deuteronomy 6:1', 'Deuteronomy', 6, 1, '&nbsp;دا ټول هغه حُکمونه دى چې مالِک خُدائ ستاسو خُدائ پاک ما له حُکم راکړے دے چې تاسو ته يې وښايم. چې په هغه مُلک کښې پرې عمل کوئ چې تاسو ورننوځئ او قبضه پرې کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4663, 'Deuteronomy 6:2', 'Deuteronomy', 6, 2, '&nbsp;او چې تر کومې پورې تاسو، ستاسو بچى او ستاسو نمسى ژوندى وى نو د مالِک خُدائ ستاسو خُدائ پاک نه خامخا يرېږئ. کۀ تاسو د هغۀ په ټول قانون عمل وکړو کوم چې زۀ تاسو له درکوم نو په هغه مُلک کښې به ستاسو عُمر زيات شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4664, 'Deuteronomy 6:3', 'Deuteronomy', 6, 3, '&nbsp;اے بنى اِسرائيلو، غوږ شئ. او په دې حُکمونو باندې عمل کوئ نو ستاسو هر کار به سم وى او په هغه مُلک کښې به مو ډېر اولاد پېدا شى چې زرخيزه او آباد دے، لکه څنګه چې مالِک خُدائ، ستاسو د پلار نيکۀ خُدائ پاک، تاسو سره وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4665, 'Deuteronomy 6:4', 'Deuteronomy', 6, 4, '&nbsp;اے بنى اِسرائيله واوره. مالِک زمونږ مالِک خُدائ واحد ذات دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4666, 'Deuteronomy 6:5', 'Deuteronomy', 6, 5, '&nbsp;تاسو د مالِک خُدائ خپل خُدائ پاک سره په پوره زړۀ سره، په پوره ځان او په خپل ټول طاقت سره مينه ساتئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4667, 'Deuteronomy 6:6', 'Deuteronomy', 6, 6, '&nbsp;کوم حُکمونه چې درکوم نو هغه په ياده ياد کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4668, 'Deuteronomy 6:7', 'Deuteronomy', 6, 7, '&nbsp;خپلو بچو ته دا بيا بيا وريادوئ. کۀ په کور کښې ناست يئ يا په لاره روان يئ، چې څملئ يا پاڅئ، نو د دې په حقله د هغوئ سره خبرې کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4669, 'Deuteronomy 6:8', 'Deuteronomy', 6, 8, '&nbsp;دا په خپلو مټو او په خپلو تندو باندې وتړئ چې ستاسو دپاره د يادېدو د نښې په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4670, 'Deuteronomy 6:9', 'Deuteronomy', 6, 9, '&nbsp;دا د خپلو کورونو په درشلو او د خپلو ښارونو په دروازو وليکئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4671, 'Deuteronomy 6:10', 'Deuteronomy', 6, 10, '&nbsp;لکه څنګه چې مالِک خُدائ ستاسو خُدائ پاک ستاسو پلار نيکۀ، اِبراهيم، اِسحاق او يعقوب سره لوظ کړے دے، هغه به تاسو له لوئ لوئ او ښائسته ښارونه درکړى کوم چې تاسو نۀ وى جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4672, 'Deuteronomy 6:11', 'Deuteronomy', 6, 11, '&nbsp;کورونه به مو د ښو ښو څيزونو نه ډک وى چې کوم تاسو په کښې اېښى نۀ وى او هلته به کوهى وى چې تاسو کنستلى نۀ وى او د انګورو او زيتُونو باغونه به وى چې تاسو کَرلى نۀ وى. کله چې مالِک خُدائ تاسو دې مُلک ته راولى نو ستا دپاره به خوراک ډېر وى او تاسو به ماړۀ شئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4673, 'Deuteronomy 6:12', 'Deuteronomy', 6, 12, '&nbsp;نو پام کوئ چې مالِک خُدائ هېر نۀ کړئ کوم چې تاسو د مِصر مُلک نه راوويستلئ، چرته چې تاسو غلامان وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4674, 'Deuteronomy 6:13', 'Deuteronomy', 6, 13, '&nbsp;مالِک خُدائ د خپل خُدائ پاک نه يرېږئ، تش د هغۀ عبادت کوئ او صِرف د هغۀ په نوم قسم خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4675, 'Deuteronomy 6:14', 'Deuteronomy', 6, 14, '&nbsp;د نورو معبودانو عبادت مۀ کوئ، د هغه خلقو د معبودانو کوم چې ستاسو په خوا او شا کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4676, 'Deuteronomy 6:15', 'Deuteronomy', 6, 15, '&nbsp;ځکه چې مالِک خُدائ ستاسو خُدائ پاک کوم چې تاسو سره اوسيږى، هغه يو غېرتى خُدائ پاک دے. د هغۀ غضب به په تاسو راشى او هغه به د زمکې مخ نه تاسو ورک کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4677, 'Deuteronomy 6:16', 'Deuteronomy', 6, 16, '&nbsp;تاسو په خپل مالِک خُدائ آزمېښت مۀ کوئ، لکه څنګه چې تاسو هغه په مسه کښې وآزمائيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4678, 'Deuteronomy 6:17', 'Deuteronomy', 6, 17, '&nbsp;پام کوئ چې د هغۀ په ټول قانون عمل کوئ کوم چې هغۀ تاسو له درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4679, 'Deuteronomy 6:18', 'Deuteronomy', 6, 18, '&nbsp;د مالِک خُدائ په نظر کښې چې څۀ صحيح او ښۀ وى نو هم هغه کوئ، نو ستاسو هر يو کار به سم وى. تاسو به هغه آبادې زمکې ته ورننه وځئ او ستاسو به شى چې مالِک خُدائ ستاسو پلار نيکۀ سره د هغې وعده کړې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4680, 'Deuteronomy 6:19', 'Deuteronomy', 6, 19, '&nbsp;او لکه چې هغۀ څنګه وعده کړې ده، تاسو به خپل دشمنان د هغه ځائ نه وشړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4681, 'Deuteronomy 6:20', 'Deuteronomy', 6, 20, '&nbsp;په راتلونکى زمانه کښې کله چې بچى درنه تپوس کوى چې مالِک خُدائ زمونږ خُدائ پاک د دې ټول قانون د منلو حُکم مونږ له ولې راکړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4682, 'Deuteronomy 6:21', 'Deuteronomy', 6, 21, '&nbsp;نو هغوئ ته ووايئ چې مونږ په مِصر کښې د فِرعون غلامان وُو او مالِک خُدائ د خپل لوئ طاقت سره مونږ بچ کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4683, 'Deuteronomy 6:22', 'Deuteronomy', 6, 22, '&nbsp;مونږ په خپلو سترګو وليدل چې هغۀ مِصريانو، فِرعون او د هغۀ ټولو آفسرانو ته خپلې معجزې او يروونکى کارونه وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4684, 'Deuteronomy 6:23', 'Deuteronomy', 6, 23, '&nbsp;هغۀ مونږ د مِصر نه آزاد کړُو چې دلته مو راولى او دا مُلک راکړى، لکه چې څنګه هغۀ زمونږ پلار نيکۀ سره وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4685, 'Deuteronomy 6:24', 'Deuteronomy', 6, 24, '&nbsp;بيا مالِک خُدائ زمونږ خُدائ پاک مونږ ته حُکم وکړو چې د هغۀ په ټول قانون به عمل کوُو او د هغۀ درناوے به کوُو. کۀ مونږ داسې وکړل نو زمونږ قوم به همېشه د هغۀ د نظر لاندې وى او کاميابى به زمونږه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4686, 'Deuteronomy 6:25', 'Deuteronomy', 6, 25, '&nbsp;کۀ مونږ په وفادارۍ سره په هغه هر څۀ عمل وکړُو چې مالِک خُدائ زمونږ خُدائ پاک يې مونږ ته حُکم کړے دے، نو هغه به زمونږ نه رضا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4687, 'Deuteronomy 7:1', 'Deuteronomy', 7, 1, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک به تاسو هغه مُلک ته وردننه کړى چې د کوم قبضه کولو له ورروان يئ او هغه به د دې نه ډېر قومونه وشړى. کله چې تاسو مخ په وړاندې ځئ، نو هغه به اووۀ قومونه وشړى کوم چې ستاسو نه لوئ او طاقتور دى. هغوئ حِتيان، جرجاسيان، اموريان، کنعانيان، فرزيان، حِويان او يبوسيان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4688, 'Deuteronomy 7:2', 'Deuteronomy', 7, 2, '&nbsp;کله چې مالِک خُدائ ستاسو خُدائ پاک تاسو په هغه خلقو زورَور کړى او شکست ورکړئ، نو هغوئ ټول ووژنئ. د هغوئ سره لوظ مۀ کوئ او چې هيڅ رحم ورباندې ونۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4689, 'Deuteronomy 7:3', 'Deuteronomy', 7, 3, '&nbsp;د هغوئ سره ودونه مۀ کوئ او خپل اولاد هغوئ سره ودونو ته مۀ پرېږدئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4690, 'Deuteronomy 7:4', 'Deuteronomy', 7, 4, '&nbsp;ځکه چې هغوئ به بيا ستاسو اولاد د مالِک خُدائ نه واړوى چې د هغوئ د معبودانو عبادت به کوى. نو بيا به د مالِک خُدائ غضب په تاسو راشى او تاسو به سمدستى تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4691, 'Deuteronomy 7:5', 'Deuteronomy', 7, 5, '&nbsp;د هغوئ د قربان‌ګاه ځايونه وران کړئ، د هغوئ مقدسې ستنې ټوټې ټوټې کړئ، د هغوئ د اشيرې بُت نښې راوغورزوئ او د هغوئ بُتان وسوزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4692, 'Deuteronomy 7:6', 'Deuteronomy', 7, 6, '&nbsp;تاسو د مالِک خُدائ يعنې د خُدائ پاک مقدس خلق يئ. نو هغۀ د زمکې د مخ نه خوښ کړئ چې د هغۀ خپل خاص خلق اوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4693, 'Deuteronomy 7:7', 'Deuteronomy', 7, 7, '&nbsp;مالِک خُدائ تاسو سره د دې دپاره مينه نۀ ده کړې او نۀ يې خوښ کړى يئ چې تاسو د نورو خلقو نه زيات وئ، په حقيقت کښې تاسو د ټولو نه وړوکے قوم وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4694, 'Deuteronomy 7:8', 'Deuteronomy', 7, 8, '&nbsp;خو مالِک خُدائ ستاسو سره مينه وکړه او هغه وعده پوره کوى کومه يې چې ستاسو پلار نيکۀ سره کړې وه. نو ځکه هغۀ د خپل لوئ طاقت سره تاسو بچ کړئ او د مِصر بادشاه، فِرعون د غلامۍ نه يې آزاد کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4695, 'Deuteronomy 7:9', 'Deuteronomy', 7, 9, '&nbsp;ياد ساتئ چې مالِک خُدائ ستاسو خُدائ پاک، حقيقى خُدائ پاک دے او هغه وفادار دے. هغه به خپل لوظ پوره کړى او د هغه خلقو زرګونو نسلونو ته به نۀ بدلېدونکې مينه وښائى څوک چې د هغۀ سره مينه لرى او د هغۀ په حُکمونو عمل کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4696, 'Deuteronomy 7:10', 'Deuteronomy', 7, 10, '&nbsp;او څوک چې ترې نه نفرت کوى نو په بدل کښې به هغه تباه کړى. هغه به هغه چا له په سزا ورکولو کښې سستى ونۀ کړى څوک چې د هغۀ نه نفرت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4697, 'Deuteronomy 7:11', 'Deuteronomy', 7, 11, '&nbsp;تاسو ته چې څۀ ښودلے شوى دى نو په هغې عمل وکړئ، نن چې ما کوم قانون درکړے دے په هغې عمل وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4698, 'Deuteronomy 7:12', 'Deuteronomy', 7, 12, '&nbsp;کۀ تاسو دې حُکمونو ته غوږ ونيسئ او په وفادارۍ سره پرې عمل کوئ، نو مالِک خُدائ ستاسو خُدائ پاک به ستاسو سره خپل لوظ پوره کړى او خپله نۀ بدلېدونکې مينه به درته وښائى، لکه څنګه چې هغۀ ستاسو پلار نيکۀ سره وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4699, 'Deuteronomy 7:13', 'Deuteronomy', 7, 13, '&nbsp;هغه به ستاسو سره مينه کوى او برکت به درکړى، نو ستاسو شمېر به زيات شى او ډېر اولاد به پېدا شى، هغه به ستاسو پټى برکتناک کړى، نو چې ستاسو غله، مے او د زيتُونو تېل به پېدا کړى، او هغه به تاسو له برکت درکړى چې تاسو له ډېر څاروى، چېلۍ او ګډې درکړى. هغه به دا ټول برکتونه تاسو له په هغه مُلک کښې درکړى د کوم چې هغۀ ستاسو پلار نيکۀ سره تاسو له د درکولو وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4700, 'Deuteronomy 7:14', 'Deuteronomy', 7, 14, '&nbsp;په دُنيا کښې د يو قوم سره به هم ستاسو په شان ډېر برکتونه نۀ وى. نۀ به ستاسو يو کس او نۀ به ستاسو يو څاروے شنډ ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');